import re
import unicodedata
import hashlib


# Exact normalized title or order-insensitive normalized author-list keys.
def exact_normalized_fields(r):
    def norm(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return " ".join(re.findall(r"[a-z0-9]+", value))

    def key(prefix, value):
        return prefix + hashlib.blake2s(value.encode(), digest_size=10).hexdigest()

    out = []
    title = norm(r.get("title", ""))
    if title:
        out.append(key("xt:", title))
    parts = [norm(x) for x in re.split(r"[,;|\n]+", r.get("authors", ""))]
    parts = sorted(set(x for x in parts if x))
    if parts:
        out.append(key("xa:", "|".join(parts)))
    return out


# Cross-attribute lexical anchors and acronyms tolerate moved text, truncation, and expanded aliases.
def lexical_cross_field(r):
    stop = {
        "about", "after", "again", "among", "based", "before", "between",
        "from", "into", "over", "through", "under", "using", "with",
        "their", "these", "those", "this", "that", "there", "where",
        "study", "analysis", "article", "paper", "report", "review",
        "abstract", "summary", "proceedings", "journal", "volume"
    }

    def fold(value):
        value = unicodedata.normalize("NFKD", value or "")
        return "".join(c for c in value if not unicodedata.combining(c))

    anchors = set()
    for field in ("title", "authors", "journal"):
        raw = fold(r.get(field, ""))
        words = re.findall(r"[A-Za-z0-9]+", raw)
        for word in words:
            w = word.casefold()
            if (len(w) >= 5 or (word.isupper() and 2 <= len(word) <= 10)) and w not in stop:
                anchors.add(w[:24])
        significant = [w for w in words if len(w) > 2 and w.casefold() not in stop]
        if 2 <= len(significant) <= 12:
            acronym = "".join(w[0] for w in significant).casefold()
            if 2 <= len(acronym) <= 12:
                anchors.add(acronym)

    return [
        "lx:" + hashlib.blake2s(a.encode(), digest_size=7).hexdigest()
        for a in sorted(anchors)
    ]


# Character-shingle minhash keys tolerate prefixes, suffixes, punctuation changes, and local OCR edits.
def character_minhash(r):
    def compact(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return "".join(re.findall(r"[a-z0-9]+", value))

    def signatures(prefix, value):
        text = compact(value)
        if not text:
            return []
        width = 4 if len(text) >= 8 else max(2, len(text) // 2)
        grams = {text[i:i + width] for i in range(max(1, len(text) - width + 1))}
        out = []
        for salt in range(4):
            best = min(
                hashlib.blake2s(
                    (str(salt) + "|" + gram).encode(), digest_size=8
                ).digest()
                for gram in grams
            )
            out.append(prefix + best.hex())
        return out

    return (
        signatures("ct:", r.get("title", ""))
        + signatures("ca:", r.get("authors", ""))
    )


# Phonetic author anchors handle initials/name variants; a sparse-record key recovers content-free pairs.
def phonetic_authors_and_sparse(r):
    def fold(value):
        value = unicodedata.normalize("NFKD", value or "")
        value = "".join(c for c in value if not unicodedata.combining(c)).casefold()
        return re.findall(r"[a-z]+", value)

    def phonetic(word):
        if not word:
            return ""
        groups = {
            **dict.fromkeys("bfpv", "1"),
            **dict.fromkeys("cgjkqsxz", "2"),
            **dict.fromkeys("dt", "3"),
            "l": "4",
            **dict.fromkeys("mn", "5"),
            "r": "6",
        }
        first = word[0]
        result, previous = [first], groups.get(first, "")
        for char in word[1:]:
            code = groups.get(char, "")
            if code and code != previous:
                result.append(code)
            previous = code
        return ("".join(result) + "0000")[:5]

    anchors = set()
    for part in re.split(r"[,;|\n]+", r.get("authors", "")):
        words = fold(part)
        if words:
            candidates = {words[-1]}
            if len(words) == 1:
                candidates.add(words[0])
            for word in candidates:
                if len(word) >= 3:
                    anchors.add(phonetic(word))

    out = ["pa:" + a for a in sorted(anchors) if a]
    if not (r.get("journal", "") or "").strip():
        out.append("sp:no-journal")
    return out


SCHEMES = {
    "exact_normalized_fields": exact_normalized_fields,
    "lexical_cross_field": lexical_cross_field,
    "character_minhash": character_minhash,
    "phonetic_authors_and_sparse": phonetic_authors_and_sparse,
}
